#
# Linker version script shared by every lib*_ext.so extension module.
#
# The plugin framework resolves exactly one symbol out of an extension: the
# module entry point. Everything else is an implementation detail and is demoted
# to LOCAL.
#
# See cmake/version_scripts/nvimgcodec.map for why the version node is anonymous.

{
    global:
        nvimgcodecExtensionModuleEntry;

    local:
        *;
};
